CREATE OR REPLACE FUNCTION public.delete_family_journey(p_journey_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_family uuid;
  r record;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.can_admin_family_journey(p_journey_id) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  select family_id into v_family from public.journeys where id = p_journey_id;
  perform set_config('family_auth.skip_row_audit', '1', true);
  for r in
    select a.id, a.storage_path, a.bucket
    from public.media_assets a
    where a.id in (
      select jm.media_id from public.journey_media jm where jm.journey_id = p_journey_id
      union
      select j.cover_media_id from public.journeys j where j.id = p_journey_id and j.cover_media_id is not null
    )
  loop
    perform family_auth.enqueue_storage_cleanup(
      v_family, null, r.bucket, r.storage_path, 'unref_private_asset', 'media_assets', r.id
    );
    delete from public.media_assets where id = r.id;
  end loop;
  delete from public.journeys where id = p_journey_id;
  perform set_config('family_auth.skip_row_audit', '0', true);
  perform family_auth.append_audit(
    v_family, null, 'family.journey.manage', 'direct',
    'journeys', p_journey_id::text, 'delete_family_journey',
    '{}'::jsonb
  );
  return jsonb_build_object('ok', true, 'id', p_journey_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_family_journey_entry(p_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_journey uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  select journey_id into v_journey from public.journey_entries where id = p_entry_id;
  if v_journey is null or not public.can_edit_family_journey_entries(v_journey) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  delete from public.journey_entries where id = p_entry_id;
  return public.get_family_journey(v_journey);
end;
$function$
